zh=dict(translations);en={key:key for key in translations}
for ch,english in chinese_to_english.items():zh[ch]=ch;en[ch]=english
for language,values in [('zh-Hans',zh),('en',en)]:
    folder=Path('app/Resources')/(language+'.lproj');folder.mkdir(exist_ok=True)
    lines=[json.dumps(k,ensure_ascii=False)+' = '+json.dumps(v,ensure_ascii=False)+';' for k,v in sorted(values.items())]
    (folder/'Localizable.strings').write_text('\n'.join(lines)+'\n')
print(f'{len(zh)} localization entries per language')
